function findNthDigit(n) {
  // Binary search for the number that holds the n-th digit, using the total digit count of 1..x.
  const digitsUpTo = x => {
    let total = 0;
    for (let low = 1, width = 1; low <= x; low *= 10, width++) {
      total += (Math.min(x, low * 10 - 1) - low + 1) * width;
    }
    return total;
  };
  let lo = 1;
  let hi = n;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (digitsUpTo(mid) >= n) hi = mid;
    else lo = mid + 1;
  }
  const offset = n - digitsUpTo(lo - 1) - 1;
  return parseInt(lo.toString().charAt(offset), 10);
}

